#!/usr/bin/env python3

sequence = ''

# Encontrar os sítios EcoRI
cut_sites = []
start = 0

while True:
    position = sequence.find("GAATTC", start)

    if position == -1:
        break

    cut_sites.append(position + 1)
    start = position + 1

# Dividir a sequência nos locais de corte
fragments = []
start = 0

for cut in cut_sites:
    fragments.append(sequence[start:cut])
    start = cut

fragments.append(sequence[start:])

# Informações dos fragmentos
start = 0

for fragment in fragments:
    end = start + len(fragment)

    print(
        "Início:", start + 1,
        "Fim:", end,
        "Comprimento:", len(fragment)
    )

    start = end

# Ordenar do maior para o menor
fragments.sort(key=len, reverse=True)

print("\nFragmentos no gel:")

for fragment in fragments:
    print(len(fragment), "bp")